/////////////////////////////////////////////////////////////////////////////
STDAPI DllGetTcCtrl(ITcCtrl** ppCtrl)
{
	if ( ppCtrl == NULL )
		return E_POINTER;

	CComObject<CTestCtrl>* pCTestCtrl = new CComObject<CTestCtrl>();
	if (pCTestCtrl == NULL) return E_POINTER;
	return pCTestCtrl->QueryInterface(IID_ITcCtrl, reinterpret_cast<void**>(ppCtrl));
}
